vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.0);
    float dp = (phase - 1.2) * 5.0;
    float pulse = exp(-dp * dp);
    float openness = mix(1.0, 0.04, clamp(pulse, 0.0, 1.0));

    vec2 p = uv;
    p.y /= openness;
    float eyeDist = length(p) - 0.35;

    vec3 skin = vec3(0.80, 0.60, 0.52) + 0.05 * uv.y;

    float r = length(uv);
    vec3 iris = palette(r * 2.5 - iTime * 0.03, vec3(0.30, 0.20, 0.10), vec3(0.30, 0.30, 0.20), vec3(1.0, 1.0, 0.5), vec3(0.0, 0.10, 0.20));
    float pupil = smoothstep(0.10, 0.085, r);
    float irisMask = smoothstep(0.23, 0.21, r);
    vec3 sclera = vec3(0.95, 0.93, 0.90);
    vec3 eyeColor = mix(sclera, iris, irisMask);
    eyeColor = mix(eyeColor, vec3(0.02), pupil);

    float highlight = smoothstep(0.06, 0.0, length(uv - vec2(-0.08, 0.09)));
    eyeColor += vec3(highlight * 0.6);
    eyeColor = clamp(eyeColor, 0.0, 1.0);

    float inside = smoothstep(0.015, -0.015, eyeDist);
    vec3 col = mix(skin, eyeColor, inside);

    float rim = smoothstep(0.02, 0.0, abs(eyeDist));
    col = mix(col, vec3(0.35, 0.18, 0.14), rim * 0.5);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.2);
    float dp = (phase - 1.3) * 5.0;
    float pulse = exp(-dp * dp);
    float openness = mix(1.0, 0.045, clamp(pulse, 0.0, 1.0));

    vec2 warp = vec2(fbm(uv * 3.0 + iTime * 0.15), fbm(uv * 3.0 + vec2(5.2, 1.3) + iTime * 0.15));
    vec2 wp = uv + (warp - 0.5) * 0.05;

    vec2 p = wp;
    p.y /= openness;
    float eyeDist = length(p) - 0.34;

    vec3 skin = vec3(0.78, 0.58, 0.5) + 0.06 * uv.y;

    float r = length(wp);
    float ang = atan(wp.y, wp.x);
    float fibers = fbm(vec2(ang * 3.0, r * 6.0) + iTime * 0.05);
    vec3 iris = palette(fibers + r, vec3(0.25, 0.15, 0.08), vec3(0.35, 0.25, 0.15), vec3(1.0, 0.8, 0.4), vec3(0.15, 0.2, 0.3));
    float pupil = smoothstep(0.095, 0.08, r);
    float irisMask = smoothstep(0.22, 0.20, r);
    vec3 sclera = vec3(0.92, 0.90, 0.88) - 0.05 * fbm(wp * 8.0);
    vec3 eyeColor = mix(sclera, iris, irisMask);
    eyeColor = mix(eyeColor, vec3(0.015), pupil);

    float inside = smoothstep(0.015, -0.015, eyeDist);
    vec3 col = mix(skin, eyeColor, inside);

    float rim = smoothstep(0.02, 0.0, abs(eyeDist));
    col = mix(col, vec3(0.3, 0.16, 0.13), rim * 0.5);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

