    float pulse = exp(-dp * dp);
    float openness = mix(1.0, 0.04, clamp(pulse, 0.0, 1.0));

    vec3 ro = vec3(0.0, 0.0, -2.6);
    vec3 rd = normalize(vec3(uv, 1.3));

    float t = 0.0;
    float d = 1.0;
    vec3 pos = ro;
    for (int i = 0; i < 32; i++) {
        pos = ro + rd * t;
        d = sdSphere(pos, 1.0);
        if (d < 0.001) break;
        t += d;
        if (t > 8.0) break;
    }

    vec3 sphereCol = vec3(0.0);
    if (d < 0.001) {
        vec3 n = normalize(pos);
        vec3 lightDir = normalize(vec3(0.5, 0.8, -0.6));
        float diff = max(dot(n, lightDir), 0.0);
        float r2 = length(n.xy);
        vec3 iris = palette(r2 * 3.5 - iTime * 0.04, vec3(0.2, 0.1, 0.05), vec3(0.3, 0.25, 0.15), vec3(1.0, 0.8, 0.5), vec3(0.1, 0.2, 0.3));
        float pupil = smoothstep(0.16, 0.14, r2);
        float irisMask = smoothstep(0.44, 0.42, r2);
        vec3 sclera = vec3(0.92);
        vec3 base = mix(sclera, iris, irisMask);
        base = mix(base, vec3(0.02), pupil);
        sphereCol = base * (0.35 + 0.75 * diff);
    }

    vec3 skin = vec3(0.83, 0.63, 0.55) + 0.05 * uv.y;

    vec2 p = uv;
    p.y /= openness;
    float eyeDist = length(p) - 0.5;
    float inside = smoothstep(0.02, -0.02, eyeDist);

    vec3 col = mix(skin, sphereCol, inside);

    float rim = smoothstep(0.02, 0.0, abs(eyeDist));
    col = mix(col, vec3(0.32, 0.17, 0.14), rim * 0.4);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.0);
    float dp = (phase - 1.2) * 5.0;
    float pulse = exp(-dp * dp);
    float openness = clamp(1.0 - pulse, 0.03, 1.0);

    float halfWidth = 0.42;
    float xn = clamp(uv.x / halfWidth, -1.0, 1.0);
    float archProfile = sqrt(max(1.0 - xn * xn, 0.0));
    float aperture = 0.30 * archProfile * openness;

    float lidMask = smoothstep(aperture + 0.012, aperture - 0.012, abs(uv.y));
    float widthMask = smoothstep(halfWidth + 0.02, halfWidth - 0.02, abs(uv.x));
    float inside = lidMask * widthMask;

    float r = length(uv);
    float ang = atan(uv.y, uv.x);
    float petals = 0.5 + 0.5 * cos(ang * 10.0 + sin(r * 18.0 - iTime * 1.2) * 1.5);
    vec3 iris = palette(petals * 0.6 + r, vec3(0.2, 0.15, 0.3), vec3(0.35, 0.3, 0.2), vec3(1.0, 0.9, 0.6), vec3(0.0, 0.15, 0.35));
    float pupil = smoothstep(0.10, 0.085, r);
    float irisMask = smoothstep(0.24, 0.22, r);
    vec3 sclera = vec3(0.95, 0.93, 0.91);
    vec3 eyeColor = mix(sclera, iris, irisMask);
    eyeColor = mix(eyeColor, vec3(0.02), pupil);

    vec3 skin = vec3(0.81, 0.61, 0.53) + 0.05 * uv.y;
    vec3 col = mix(skin, eyeColor, inside);

    float rimDist = abs(abs(uv.y) - aperture);
    float rim = smoothstep(0.02, 0.0, rimDist) * widthMask;
    col = mix(col, vec3(0.32, 0.17, 0.13), rim * 0.4);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    return vec2(hash21(p), hash21(p + vec2(37.1, 17.7)));
}

float voronoi(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minDist = 1.5;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 point = hash22(ip + neighbor);
            vec2 diff = neighbor + point - fp;
            float d = length(diff);
            minDist = min(minDist, d);
        }
    }
    return minDist;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.2);
    float dp = (phase - 1.3) * 5.0;
    float pulse = exp(-dp * dp);
    float openness = clamp(1.0 - pulse, 0.03, 1.0);

    float halfWidth = 0.40;
    float xn = clamp(uv.x / halfWidth, -1.0, 1.0);
    float archTop = 0.27 * sqrt(1.0 - xn * xn);
    float archBot = 0.21 * sqrt(1.0 - xn * xn);
    float upperY = archTop * openness;
    float lowerY = -archBot * openness;

    float topMask = smoothstep(upperY + 0.012, upperY - 0.012, uv.y);
    float botMask = smoothstep(lowerY - 0.012, lowerY + 0.012, uv.y);
    float widthMask = smoothstep(halfWidth + 0.02, halfWidth - 0.02, abs(uv.x));
    float inside = topMask * botMask * widthMask;

    float r = length(uv);
    float veins = voronoi(uv * 10.0);
    vec3 scleraBase = vec3(0.94, 0.92, 0.90);
    vec3 scleraVeins = mix(vec3(0.85, 0.3, 0.28), scleraBase, smoothstep(0.0, 0.35, veins));
    float irisCells = voronoi(uv * 22.0 + iTime * 0.02);
    vec3 iris = palette(irisCells + r * 1.5, vec3(0.15, 0.2, 0.25), vec3(0.3, 0.3, 0.2), vec3(0.8, 1.0, 0.6), vec3(0.1, 0.05, 0.2));
    float pupil = smoothstep(0.10, 0.085, r);
    float irisMask = smoothstep(0.23, 0.21, r);
    vec3 eyeColor = mix(scleraVeins, iris, irisMask);
    eyeColor = mix(eyeColor, vec3(0.02), pupil);

    vec3 skin = vec3(0.79, 0.59, 0.51) + 0.05 * uv.y;
    vec3 col = mix(skin, eyeColor, inside);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

