}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);

    vec3 accum = vec3(0.0);
    float totalWeight = 0.0;

    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float tOffset = iTime - fi * 0.035;
        float weight = exp(-fi * 0.45);

        float phase = mod(tOffset, 3.0);
        float dp = (phase - 1.2) * 5.0;
        float pulse = exp(-dp * dp);
        float openness = mix(1.0, 0.04, clamp(pulse, 0.0, 1.0));

        vec2 p = uv;
        p.y /= openness;
        float eyeDist = length(p) - 0.35;
        float inside = smoothstep(0.02, -0.02, eyeDist);

        vec3 iris = palette(r * 2.5 + fi * 0.02, vec3(0.28, 0.18, 0.1), vec3(0.3, 0.28, 0.18), vec3(1.0, 0.9, 0.5), vec3(0.05, 0.1, 0.25));
        float pupil = smoothstep(0.10, 0.085, r);
        float irisMask = smoothstep(0.22, 0.20, r);
        vec3 sclera = vec3(0.94, 0.92, 0.9);
        vec3 eyeColor = mix(sclera, iris, irisMask);
        eyeColor = mix(eyeColor, vec3(0.02), pupil);

        vec3 skin = vec3(0.80, 0.60, 0.52) + 0.05 * uv.y;
        vec3 samp = mix(skin, eyeColor, inside);

        accum += samp * weight;
        totalWeight += weight;
    }

    vec3 col = accum / totalWeight;
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

