void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec2 warp = vec2(fbm(uv * 3.0 + iTime * 0.15), fbm(uv * 3.0 + vec2(5.2, 1.3) + iTime * 0.15));
    vec2 wp = uv + (warp - 0.5) * 0.05;

    float R = 0.34;
    float eyeDist = length(wp) - R;

    vec3 skin = vec3(0.78, 0.58, 0.5) + 0.06 * uv.y;

    float r = length(wp);
    float ang = atan(wp.y, wp.x);
    float fibers = fbm(vec2(ang * 3.0, r * 6.0) + iTime * 0.05);
    vec3 iris = palette(fibers + r, vec3(0.25, 0.15, 0.08), vec3(0.35, 0.25, 0.15), vec3(1.0, 0.8, 0.4), vec3(0.15, 0.2, 0.3));
    float pupil = smoothstep(0.095, 0.08, r);
    float irisMask = smoothstep(0.22, 0.20, r);
    vec3 sclera = vec3(0.92, 0.90, 0.88) - 0.05 * fbm(wp * 8.0);
    vec3 eyeColor = mix(sclera, iris, irisMask);
    eyeColor = mix(eyeColor, vec3(0.015), pupil);

    float circleMask = smoothstep(0.015, -0.015, eyeDist);

    float x = uv.x;
    float yb = sqrt(max(0.0, R * R - x * x));
    float upFrac = 0.7;
    float meet = yb * (1.0 - 2.0 * upFrac);
    float edgeNoise = (fbm(vec2(x * 8.0 + iTime * 0.02, 3.1)) - 0.5) * 0.02;
    float edgeW = 0.008;

    float insideAcc = 0.0;
    for (int s = 0; s < 2; s++) {
        float ts = iTime - float(s) * 0.045;
        float phase = mod(ts, 3.2);
        float dp = (phase - 1.3) * 5.0;
        float pulse = exp(-dp * dp);
        float lidClose = clamp(pulse, 0.0, 1.0);
        float uY = mix(yb, meet, lidClose) + edgeNoise;
        float lY = mix(-yb, meet, lidClose) + edgeNoise * 0.5;
        float mU = 1.0 - smoothstep(uY - edgeW, uY + edgeW, uv.y);
        float mL = smoothstep(lY - edgeW, lY + edgeW, uv.y);
        insideAcc += mU * mL;
    }
    float inside = (insideAcc * 0.5) * circleMask;

    vec3 col = mix(skin, eyeColor, inside);

    float rim = smoothstep(0.02, 0.0, abs(eyeDist));
    col = mix(col, vec3(0.3, 0.16, 0.13), rim * 0.5 * inside);

    float phaseNow = mod(iTime, 3.2);
    float dpNow = (phaseNow - 1.3) * 5.0;
    float lidCloseNow = clamp(exp(-dpNow * dpNow), 0.0, 1.0);
    float upperNow = mix(yb, meet, lidCloseNow) + edgeNoise;
    float lowerNow = mix(-yb, meet, lidCloseNow) + edgeNoise * 0.5;
    float creaseU = smoothstep(0.02, 0.0, abs(uv.y - upperNow)) * circleMask;
    float creaseL = smoothstep(0.02, 0.0, abs(uv.y - lowerNow)) * circleMask;
    col = mix(col, vec3(0.28, 0.15, 0.12), (creaseU + creaseL) * 0.5);

    float lashBand = smoothstep(0.05, 0.0, uv.y - upperNow) * step(0.0, uv.y - upperNow);
    float lashPattern = smoothstep(0.6, 1.0, sin(x * 90.0));
    float widthMask = smoothstep(R + 0.02, R - 0.03, abs(x));
    col = mix(col, vec3(0.04, 0.03, 0.02), lashBand * lashPattern * (1.0 - lidCloseNow) * widthMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

