float voronoi(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minD = 8.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 g = vec2(float(x), float(y));
            vec2 o = vec2(hash21(ip + g), hash21(ip + g + vec2(17.3, 9.1)));
            vec2 r = g + o - fp;
            float dd = dot(r, r);
            minD = min(minD, dd);
        }
    }
    return sqrt(minD);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float R = 0.42;
    float x = uv.x;
    float r = length(uv);
    float ang = atan(uv.y, uv.x);

    float cells = voronoi(vec2(ang * 2.5, r * 5.0) + vec2(0.0, iTime * 0.03));
    vec3 iris = palette(cells + r * 1.5 - iTime * 0.02, vec3(0.15, 0.1, 0.1), vec3(0.3, 0.25, 0.2), vec3(1.0, 0.9, 0.6), vec3(0.2, 0.15, 0.3));
    float pupil = smoothstep(0.1, 0.08, r);
    float irisMask = smoothstep(0.36, 0.34, r);
    vec3 sclera = vec3(0.93, 0.91, 0.88) - 0.06 * voronoi(uv * 6.0);
    vec3 eyeColor = mix(sclera, iris, irisMask);
    eyeColor = mix(eyeColor, vec3(0.01), pupil);

    vec3 skin = vec3(0.8, 0.6, 0.52) + 0.05 * uv.y;

    float circleMask = smoothstep(0.015, -0.015, r - R);

    float yb = sqrt(max(0.0, R * R - x * x));
    float gap = 0.012;
    float edgeW = 0.01;

    const int MB_SAMPLES = 5;
    float insideAcc = 0.0;
    for (int i = 0; i < MB_SAMPLES; i++) {
        float ft = (float(i) / float(MB_SAMPLES - 1)) - 0.5;
        float ts = iTime + ft * 0.06;
        float phase = mod(ts, 3.0);
        float dp = (phase - 1.2) * 5.0;
        float pulse = exp(-dp * dp);
        float lidClose = clamp(pulse, 0.0, 1.0);
        float upperLidY = mix(yb, gap, lidClose);
        float lowerLidY = mix(-yb, -gap, lidClose);
        float mU = 1.0 - smoothstep(upperLidY - edgeW, upperLidY + edgeW, uv.y);
        float mL = smoothstep(lowerLidY - edgeW, lowerLidY + edgeW, uv.y);
        insideAcc += mU * mL;
    }
    float lidMask = insideAcc / float(MB_SAMPLES);
    float inside = circleMask * lidMask;

    vec3 col = mix(skin, eyeColor, inside);

    float phaseNow = mod(iTime, 3.0);
    float dpNow = (phaseNow - 1.2) * 5.0;
    float lidCloseNow = clamp(exp(-dpNow * dpNow), 0.0, 1.0);
    float upperNow = mix(yb, gap, lidCloseNow);
    float lowerNow = mix(-yb, -gap, lidCloseNow);
    float creaseU = smoothstep(0.02, 0.0, abs(uv.y - upperNow)) * circleMask;
    float creaseL = smoothstep(0.02, 0.0, abs(uv.y - lowerNow)) * circleMask;
    col = mix(col, vec3(0.26, 0.14, 0.12), (creaseU + creaseL) * 0.5);

    float lashBand = smoothstep(0.05, 0.0, uv.y - upperNow) * step(0.0, uv.y - upperNow);
    float lashPattern = smoothstep(0.6, 1.0, sin(x * 85.0));
    float widthMask = smoothstep(R + 0.02, R - 0.03, abs(x));
    col = mix(col, vec3(0.04, 0.03, 0.02), lashBand * lashPattern * (1.0 - lidCloseNow) * widthMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

