void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.0);
    float dp = (phase - 1.2) * 5.0;
    float pulse = exp(-dp * dp);
    float lidClose = clamp(pulse, 0.0, 1.0);

    vec3 ro = vec3(0.0, 0.0, -2.6);
    vec3 rd = normalize(vec3(uv, 1.3));

    float Rl = 1.4;
    vec3 cUp = vec3(0.0, mix(1.7, 0.12, lidClose), -0.35);
    vec3 cLo = vec3(0.0, mix(-1.7, -0.12, lidClose), -0.35);

    float t = 0.0;
    vec3 pos = ro;
    int hitType = 0;
    for (int i = 0; i < 40; i++) {
        pos = ro + rd * t;
        float dEye = sdSphere(pos, 1.0);
        float dUp = length(pos - cUp) - Rl;
        float dLo = length(pos - cLo) - Rl;
        float dMin = min(dEye, min(dUp, dLo));
        if (dMin < 0.001) {
            if (dEye <= dUp && dEye <= dLo) { hitType = 1; }
            else if (dUp <= dLo) { hitType = 2; }
            else { hitType = 3; }
            break;
        }
        t += dMin;
        if (t > 8.0) break;
    }

    vec3 skinFace = vec3(0.83, 0.63, 0.55) + 0.05 * uv.y;
    vec3 col;

    if (hitType == 0) {
        col = skinFace;
    } else if (hitType == 1) {
        vec3 n = normalize(pos);
        vec3 lightDir = normalize(vec3(0.5, 0.8, -0.6));
        float diff = max(dot(n, lightDir), 0.0);
        float r2 = length(n.xy);
        vec3 iris = palette(r2 * 3.5 - iTime * 0.04, vec3(0.2, 0.1, 0.05), vec3(0.3, 0.25, 0.15), vec3(1.0, 0.8, 0.5), vec3(0.1, 0.2, 0.3));
        float pupilM = smoothstep(0.16, 0.14, r2);
        float irisMask = smoothstep(0.44, 0.42, r2);
        vec3 sclera = vec3(0.92);
        vec3 base = mix(sclera, iris, irisMask);
        base = mix(base, vec3(0.02), pupilM);
        col = base * (0.35 + 0.75 * diff);
    } else {
        vec3 lidCenter = (hitType == 2) ? cUp : cLo;
        vec3 n = normalize(pos - lidCenter);
        vec3 lightDir = normalize(vec3(0.4, 0.6, -0.7));
        float diff = max(dot(n, lightDir), 0.0);
        vec3 lidSkin = vec3(0.8, 0.6, 0.52);
        float spec = pow(diff, 20.0);
        col = lidSkin * (0.4 + 0.7 * diff) + vec3(1.0) * spec * 0.3;
    }

    float R = 0.5;
    float outerMask = smoothstep(0.02, -0.02, length(uv) - R);
    col = mix(skinFace, col, outerMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

