        float diff = max(dot(n, lightDir), 0.0);
        float r2 = length(n.xy);
        vec3 iris = palette(r2 * 3.5 - iTime * 0.04, vec3(0.2, 0.1, 0.05), vec3(0.3, 0.25, 0.15), vec3(1.0, 0.8, 0.5), vec3(0.1, 0.2, 0.3));
        float pupil = smoothstep(0.16, 0.14, r2);
        float irisMask = smoothstep(0.44, 0.42, r2);
        vec3 sclera = vec3(0.92);
        vec3 base = mix(sclera, iris, irisMask);
        base = mix(base, vec3(0.02), pupil);
        sphereCol = base * (0.35 + 0.75 * diff);
    }

    vec3 skin = vec3(0.83, 0.63, 0.55) + 0.05 * uv.y;

    float R = 0.5;
    float x = uv.x;
    float rL = 0.95;
    float hOpen = mix(0.46, 0.01, lidClose);
    float baseCurve = sqrt(max(0.0, rL * rL - x * x)) - (rL - hOpen);
    float upperLidY = baseCurve;
    float lowerLidY = -baseCurve;
    float edgeW = 0.01;

    float circleMask = smoothstep(0.02, -0.02, length(uv) - R);
    float maskUpper = 1.0 - smoothstep(upperLidY - edgeW, upperLidY + edgeW, uv.y);
    float maskLower = smoothstep(lowerLidY - edgeW, lowerLidY + edgeW, uv.y);
    float inside = circleMask * maskUpper * maskLower;

    vec3 col = mix(skin, sphereCol, inside);

    float distInU = upperLidY - uv.y;
    float shadowU = (1.0 - smoothstep(0.0, 0.1, distInU)) * inside;
    float distInL = uv.y - lowerLidY;
    float shadowL = (1.0 - smoothstep(0.0, 0.08, distInL)) * inside;
    col = mix(col, col * 0.55, clamp(shadowU + shadowL, 0.0, 1.0) * 0.55);

    float lidTU = 0.12;
    float distOutU = uv.y - upperLidY;
    float bandU = smoothstep(-edgeW, edgeW, distOutU) * (1.0 - smoothstep(lidTU - edgeW, lidTU + edgeW, distOutU)) * circleMask;
    float tU = clamp(distOutU / lidTU, 0.0, 1.0);
    vec3 lidColU = mix(vec3(0.78, 0.55, 0.47), vec3(0.90, 0.70, 0.60), tU);
    lidColU = mix(lidColU, lidColU * 1.15, smoothstep(0.5, 1.0, tU));
    col = mix(col, lidColU, bandU);

    float creaseU = smoothstep(0.02, 0.0, abs(distOutU - lidTU * 0.75)) * circleMask;
    col = mix(col, col * 0.55, creaseU * 0.6);

    float lidTL = 0.07;
    float distOutL = lowerLidY - uv.y;
    float bandL = smoothstep(-edgeW, edgeW, distOutL) * (1.0 - smoothstep(lidTL - edgeW, lidTL + edgeW, distOutL)) * circleMask;
    float tL = clamp(distOutL / lidTL, 0.0, 1.0);
    vec3 lidColL = mix(vec3(0.76, 0.53, 0.45), vec3(0.86, 0.66, 0.57), tL);
    col = mix(col, lidColL, bandL);

    float lashPattern = smoothstep(0.5, 1.0, sin(x * 70.0 + 2.0));
    float lashU = smoothstep(edgeW, 0.0, abs(distOutU)) * lashPattern * circleMask;
    float lashL = smoothstep(edgeW, 0.0, abs(distOutL)) * lashPattern * 0.7 * circleMask;
    col = mix(col, vec3(0.04, 0.03, 0.02), clamp(lashU + lashL, 0.0, 1.0));

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.0);
    float dp = (phase - 1.2) * 5.0;
    float pulse = exp(-dp * dp);
    float lidClose = clamp(pulse, 0.0, 1.0);

    vec3 ro = vec3(0.0, 0.0, -2.6);
    vec3 rd = normalize(vec3(uv, 1.3));

    float t = 0.0;
    float d = 1.0;
    vec3 pos = ro;
    for (int i = 0; i < 32; i++) {
        pos = ro + rd * t;
        d = sdSphere(pos, 1.0);
        if (d < 0.001) break;
        t += d;
        if (t > 8.0) break;
    }

    vec3 sphereCol = vec3(0.0);
    if (d < 0.001) {
        vec3 n = normalize(pos);
        vec3 lightDir = normalize(vec3(0.5, 0.8, -0.6));
        float diff = max(dot(n, lightDir), 0.0);
        float r2 = length(n.xy);
        vec3 iris = palette(r2 * 3.5 - iTime * 0.04, vec3(0.2, 0.1, 0.05), vec3(0.3, 0.25, 0.15), vec3(1.0, 0.8, 0.5), vec3(0.1, 0.2, 0.3));
        float pupil = smoothstep(0.16, 0.14, r2);
        float irisMask = smoothstep(0.44, 0.42, r2);
        vec3 sclera = vec3(0.92);
        vec3 base = mix(sclera, iris, irisMask);
        base = mix(base, vec3(0.02), pupil);
        sphereCol = base * (0.35 + 0.75 * diff);
    }

    vec3 skin = vec3(0.83, 0.63, 0.55) + 0.05 * uv.y;

    float R = 0.5;
    float x = uv.x;
    float x0 = x - 0.05;

    float rU = 0.98;
    float hOpenU = mix(0.47, 0.015, lidClose);
    float upperLidY = sqrt(max(0.0, rU * rU - x0 * x0)) - (rU - hOpenU);

    float rLo = 1.10;
    float hOpenL = mix(0.44, 0.01, lidClose);
    float lowerLidY = -(sqrt(max(0.0, rLo * rLo - x0 * x0)) - (rLo - hOpenL));

    float edgeW = 0.01;
    float circleMask = smoothstep(0.02, -0.02, length(uv) - R);
    float maskUpper = 1.0 - smoothstep(upperLidY - edgeW, upperLidY + edgeW, uv.y);
    float maskLower = smoothstep(lowerLidY - edgeW, lowerLidY + edgeW, uv.y);
    float inside = circleMask * maskUpper * maskLower;

    vec3 col = mix(skin, sphereCol, inside);

    float parallax = lidClose * 0.025;
    float highU = smoothstep(0.016, 0.0, abs(uv.y - upperLidY - parallax)) * circleMask;
    float highL = smoothstep(0.014, 0.0, abs(uv.y - lowerLidY + parallax * 0.6)) * circleMask;
    col = mix(col, vec3(1.0, 0.93, 0.85), highU * 0.55);
    col = mix(col, vec3(0.92, 0.78, 0.7), highL * 0.3);

    float shadowU = (1.0 - smoothstep(0.0, 0.09, upperLidY - uv.y)) * inside;
    float shadowL = (1.0 - smoothstep(0.0, 0.07, uv.y - lowerLidY)) * inside;
    col = mix(col, col * 0.5, clamp(shadowU + shadowL, 0.0, 1.0) * 0.5);

    float lashSaw = abs(fract(x * 13.0 + 0.5) - 0.5) * 2.0;
    float lashShapeU = smoothstep(0.35, 0.0, lashSaw) * smoothstep(0.02, 0.0, uv.y - upperLidY) * step(0.0, uv.y - upperLidY);
    float lashShapeL = smoothstep(0.35, 0.0, lashSaw) * smoothstep(0.015, 0.0, lowerLidY - uv.y) * step(0.0, lowerLidY - uv.y) * 0.6;
    float widthMask = smoothstep(R + 0.02, R - 0.03, abs(x));
    col = mix(col, vec3(0.05, 0.03, 0.02), clamp(lashShapeU + lashShapeL, 0.0, 1.0) * widthMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float sdVesica(vec2 p, float r, float w) {
    p = abs(p);
    float b = sqrt(max(r * r - w * w, 0.0));
    return ((p.y - b) * w > p.x * b) ? length(p - vec2(0.0, b)) : length(p - vec2(-w, 0.0)) - r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.0);
    float dp = (phase - 1.2) * 5.0;
    float pulse = exp(-dp * dp);
    float lidClose = clamp(pulse, 0.0, 1.0);

    float r = 0.62;
    float w = mix(0.24, 0.615, lidClose);
    vec2 pv = uv.yx;
    float eyeD = sdVesica(pv, r, w);

    vec3 skin = vec3(0.83, 0.63, 0.55) + 0.05 * uv.y;
    vec3 col = skin;

    float eyeMask = smoothstep(0.012, -0.012, eyeD);

    float rr = length(uv);
    float ang = atan(uv.y, uv.x + 1e-5);
    vec3 sclera = mix(vec3(0.96, 0.90, 0.80), vec3(0.86, 0.72, 0.60), smoothstep(0.2, 0.42, rr));
    float veinN = noise(vec2(ang * 4.0, rr * 10.0));
    float vein = smoothstep(0.82, 0.95, veinN) * smoothstep(0.18, 0.4, rr);
    sclera = mix(sclera, vec3(0.80, 0.30, 0.28), vein * 0.35);

    float irisR = 0.20;
    float irisMask = smoothstep(irisR, irisR - 0.02, rr);
    float streaks = noise(vec2(ang * 3.0, rr * 8.0 - iTime * 0.08));
    vec3 iris = mix(vec3(0.10, 0.22, 0.20), vec3(0.30, 0.55, 0.45), streaks);
    float limbal = smoothstep(irisR - 0.02, irisR - 0.005, rr);
    iris = mix(iris, vec3(0.04, 0.06, 0.05), limbal);

    float pupilR = 0.075;
    float pupil = smoothstep(pupilR, pupilR - 0.015, rr);

    vec3 eyeCol = mix(sclera, iris, irisMask);
    eyeCol = mix(eyeCol, vec3(0.015), pupil);

    float specAng = abs(ang - 2.4);
    float spec = smoothstep(0.25, 0.0, specAng) * smoothstep(0.06, 0.02, rr - 0.03) * 0.6;
    eyeCol += spec;

    col = mix(col, eyeCol, eyeMask);

    float creaseD = sdVesica(pv, r + 0.035, w + 0.02);
    float crease = smoothstep(0.015, 0.0, abs(creaseD)) * (1.0 - eyeMask);
    col = mix(col, vec3(0.62, 0.42, 0.36), crease * 0.5);

    float lash = smoothstep(0.05, 0.0, abs(eyeD)) * smoothstep(0.5, 0.0, abs(uv.x)) * (1.0 - eyeMask);
    col = mix(col, vec3(0.05, 0.03, 0.02), lash * (1.0 - lidClose) * 0.6);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float phase = mod(iTime, 3.0);
    float dp = (phase - 1.2) * 5.0;
    float pulse = exp(-dp * dp);
    float lidClose = clamp(pulse, 0.0, 1.0);

    vec3 skin = vec3(0.83, 0.63, 0.55) + 0.05 * uv.y;

    float R = 0.42;
    float x = uv.x;

    float openAmt = mix(1.0, 0.03, lidClose);
    float profile = cos(clamp(x / R, -1.0, 1.0) * 1.5708);
    float upperLidY = profile * R * openAmt * 0.95;
    float lowerLidY = -profile * R * (mix(1.0, 0.02, lidClose)) * 0.85;
    float edgeW = 0.01;

    float rr = length(uv);
    float circleMask = smoothstep(0.015, -0.015, rr - R);
    float maskUpper = 1.0 - smoothstep(upperLidY - edgeW, upperLidY + edgeW, uv.y);
    float maskLower = smoothstep(lowerLidY - edgeW, lowerLidY + edgeW, uv.y);
    float inside = circleMask * maskUpper * maskLower;

    float ang = atan(uv.y, x + 1e-5);

    vec2 wp = vec2(cos(ang), sin(ang)) * rr * 6.0;
    vec2 warp = vec2(fbm(wp + iTime * 0.06), fbm(wp + 5.1 - iTime * 0.05));
    float pattern = fbm(wp * 0.6 + warp * 2.0);

    float irisR = 0.20;
    float irisMask = smoothstep(irisR, irisR - 0.02, rr);
    vec3 iris = palette(pattern * 0.8 + rr, vec3(0.25, 0.15, 0.06), vec3(0.25, 0.2, 0.12), vec3(1.0, 0.9, 0.6), vec3(0.1, 0.25, 0.4));
    float limbal = smoothstep(irisR - 0.02, irisR - 0.004, rr);
    iris = mix(iris, vec3(0.04, 0.03, 0.02), limbal);

    float pupilR = 0.075 + 0.01 * sin(iTime * 0.5);
    float pupil = smoothstep(pupilR, pupilR - 0.015, rr);

    vec3 sclera = mix(vec3(0.97, 0.91, 0.82), vec3(0.87, 0.73, 0.61), smoothstep(0.18, 0.4, rr));
    float veins = smoothstep(0.85, 0.97, noise(vec2(ang * 5.0, rr * 12.0)));
    sclera = mix(sclera, vec3(0.80, 0.30, 0.27), veins * smoothstep(0.18, 0.4, rr) * 0.3);

    vec3 eyeCol = mix(sclera, iris, irisMask);
    eyeCol = mix(eyeCol, vec3(0.015), pupil);

    vec3 col = mix(skin, eyeCol, inside);

    float creaseU = smoothstep(0.02, 0.0, abs(uv.y - upperLidY)) * circleMask;
    float creaseL = smoothstep(0.02, 0.0, abs(uv.y - lowerLidY)) * circleMask;
    col = mix(col, vec3(0.6, 0.4, 0.34), (creaseU + creaseL) * 0.4);

    float lashPattern = smoothstep(0.5, 1.0, sin(x * 90.0 + 1.2));
    float lashBand = smoothstep(0.05, 0.0, uv.y - upperLidY) * step(0.0, uv.y - upperLidY);
    float widthMask = smoothstep(R + 0.02, R - 0.03, abs(x));
    col = mix(col, vec3(0.05, 0.03, 0.02), lashBand * lashPattern * (1.0 - lidClose) * widthMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
